function tokenize(s){ if(s.trim()==='')return []; return s.split(/\s+/); }
var e=tokenize(''), n=tokenize('a b');
console.log('FIXED: tokenize("") -> '+JSON.stringify(e)+', tokenize("a b") -> '+JSON.stringify(n));
assert(JSON.stringify(e)==='[]','fixed: empty input yields zero tokens');
assert(JSON.stringify(n)==='["a","b"]','fixed: normal input still tokenizes');

function average(vals){ if(vals.length===0)return null; return vals.reduce(function(a,b){return a+b;},0)/vals.length; }
var e=average([]), n=average([10,20]);
console.log('FIXED: average([]) -> '+e+', average([10,20]) -> '+n);
assert(e===null,'fixed: empty input returns explicit null, not NaN');
assert(n===15,'fixed: normal average correct');
assert(e!==e?false:true,'fixed: no NaN identity trap (null===null)');

function normalize(o){var out={}; Object.keys(o).forEach(function(k){out[k]=(o[k]===undefined?null:o[k]);}); return out;}
var rec=normalize({a:1,b:undefined,c:null});
var back=JSON.parse(JSON.stringify(rec));
console.log('FIXED: keys after round-trip = '+JSON.stringify(Object.keys(back)));
assert(JSON.stringify(Object.keys(back))==='["a","b","c"]','fixed: all keys survive');
assert(back.b===null,'fixed: undefined became explicit null');

function sumClean(vals){var s=0,bad=0; vals.forEach(function(v){var n=Number(v); if(Number.isFinite(n))s+=n; else bad++;}); return {sum:s,bad:bad};}
var r=sumClean([10,20,Number('abc'),30]);
console.log('FIXED: sum='+r.sum+', quarantined='+r.bad);
assert(r.sum===60,'fixed: finite values still sum correctly');
assert(r.bad===1,'fixed: exactly one bad value quarantined');
assert(Number.isFinite(r.sum),'fixed: total is finite');

