var z=rate(100,0), n=rate(100,4);
console.log('FIXED: rate(100,0) -> '+JSON.stringify(z)+', rate(100,4) -> '+n.rate);
assert(z.rate===null && z.reason,'fixed: zero denominator returns explicit null');
assert(n.rate===25000,'fixed: normal rate correct (100 records / 4ms)');
