var out=stringifySafe(obj);
var back=JSON.parse(out);
console.log('FIXED: serialized = '+out);
assert(back.self.$ref===1,'fixed: cycle replaced with $ref marker');
assert(out.indexOf('Converting circular')===-1,'fixed: no throw');

