function parseStrict(text){
  var i=0;
  var BS=String.fromCharCode(92);
  function ws(){while(i<text.length&&(text[i]===' '||text[i]==='\t'||text[i]==='\n'||text[i]==='\r'))i++;}
  function parseString(){var s='';i++;for(;;){var c=text[i++];
    if(c==='"')return s;
    if(c===BS){var e=text[i++];var m={};m['"']='"';m[BS]=BS;m['/']='/';m['b']='\b';m['f']='\f';m['n']='\n';m['r']='\r';m['t']='\t';s+=(m[e]!==undefined?m[e]:e);}
    else s+=c;}}
  function expectLit(w){if(text.substr(i,w.length)!==w)throw new Error('bad literal');i+=w.length;}
  function parseValue(){ws();var c=text[i];
    if(c==='{')return parseObject();
    if(c==='['){i++;var a=[];ws();if(text[i]===']'){i++;return a;}
      for(;;){a.push(parseValue());ws();var d=text[i++];if(d===',')continue;if(d===']')return a;throw new Error('bad array');}}
    if(c==='"')return parseString();
    if(c==='t'){expectLit('true');return true;}
    if(c==='f'){expectLit('false');return false;}
    if(c==='n'){expectLit('null');return null;}
    var j=i;if(text[j]==='-')j++;
    while(j<text.length&&text[j]>='0'&&text[j]<='9')j++;
    if(text[j]==='.'){j++;while(j<text.length&&text[j]>='0'&&text[j]<='9')j++;}
    if(j===i)throw new Error('unexpected char '+c);
    var n=Number(text.slice(i,j));i=j;return n;}
  function parseObject(){i++;var o={},seen={};ws();
    if(text[i]==='}'){i++;return o;}
    for(;;){ws();var k=parseString();ws();
      if(text[i]!==':')throw new Error('expected colon');i++;
      var v=parseValue();
      if(seen[k])throw new Error('duplicate key: '+k);seen[k]=1;o[k]=v;
      ws();var d=text[i++];if(d===',')continue;if(d==='}')return o;throw new Error('bad object');}}
  ws();var v=parseValue();ws();
  if(i!==text.length)throw new Error('trailing data');
  return v;}
var threw=false,msg='';
try{parseStrict('{"a":1,"a":2}');}catch(e){threw=true;msg=e.message;}
var ok=parseStrict('{"a":1,"b":2,"n":null,"t":true,"arr":[1,2]}');
console.log('FIXED: duplicate rejected='+threw+' ('+msg+'), clean a='+ok.a);
assert(threw===true,'fixed: duplicate key loudly rejected');
assert(/duplicate key/.test(msg),'fixed: error names the duplicate');
assert(ok.a===1&&ok.b===2&&ok.arr.length===2,'fixed: clean payload parses fully');
